//! A tiny command line scanner with the same observable behaviour as the one
//! used by the reference implementation: options are looked up by name and
//! removed from the argument list, whatever is left is reported back.

use std::ffi::{OsStr, OsString};

#[derive(Debug)]
pub enum ArgError {
    NonUtf8Argument,
    OptionWithoutAValue(&'static str),
    ParsingFailed { value: String, cause: String },
}

impl std::fmt::Display for ArgError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            ArgError::NonUtf8Argument => write!(f, "argument is not a UTF-8 string"),
            ArgError::OptionWithoutAValue(key) => {
                write!(f, "the '{}' option doesn't have an associated value", key)
            }
            ArgError::ParsingFailed { value, cause } => {
                write!(f, "failed to parse '{}': {}", value, cause)
            }
        }
    }
}

pub struct Args(Vec<OsString>);

fn is_short(key: &str) -> bool {
    !key.starts_with("--")
}

fn ends_with_byte(s: &str, c: u8) -> bool {
    s.as_bytes().last() == Some(&c)
}

impl Args {
    pub fn from_env() -> Args {
        Args(std::env::args_os().skip(1).collect())
    }

    fn index_of(&self, keys: &[&'static str]) -> Option<(usize, &'static str)> {
        for key in keys {
            if key.is_empty() {
                continue;
            }
            if let Some(i) = self.0.iter().position(|v| v == OsStr::new(key)) {
                return Some((i, key));
            }
        }
        None
    }

    fn index_of2(&self, keys: &[&'static str]) -> Option<(usize, &'static str)> {
        for key in keys {
            if key.is_empty() {
                continue;
            }
            let pos = self.0.iter().position(|v| match v.to_str() {
                Some(s) => {
                    if is_short(key) {
                        s.starts_with(key)
                    } else {
                        s.starts_with(key) && s.as_bytes().get(key.len()) == Some(&b'=')
                    }
                }
                None => false,
            });
            if let Some(i) = pos {
                return Some((i, key));
            }
        }
        None
    }

    /// Check (and consume) a flag. Combined short flags like `-abc` are
    /// supported: only the matching letter is removed.
    pub fn contains(&mut self, keys: &[&'static str]) -> bool {
        if let Some((idx, _)) = self.index_of(keys) {
            self.0.remove(idx);
            return true;
        }
        for key in keys {
            if key.is_empty() || !is_short(key) {
                continue;
            }
            let flag = match key.chars().nth(1) {
                Some(c) => c,
                None => continue,
            };
            for item in self.0.iter_mut() {
                let s = match item.to_str() {
                    Some(s) => s,
                    None => continue,
                };
                if s.starts_with('-') && !s.starts_with("--") && s.chars().count() > 2 {
                    if let Some(pos) = s[1..].find(flag) {
                        let mut new = String::with_capacity(s.len());
                        new.push_str(&s[..1 + pos]);
                        new.push_str(&s[1 + pos + flag.len_utf8()..]);
                        *item = OsString::from(new);
                        return true;
                    }
                }
            }
        }
        false
    }

    /// Fetch (and consume) the value of an option, if present.
    pub fn opt_value(&mut self, keys: &[&'static str]) -> Result<Option<String>, ArgError> {
        if let Some((idx, key)) = self.index_of(keys) {
            if idx + 1 >= self.0.len() {
                return Err(ArgError::OptionWithoutAValue(key));
            }
            let value = self.0.remove(idx + 1);
            self.0.remove(idx);
            return match value.into_string() {
                Ok(v) => Ok(Some(v)),
                Err(_) => Err(ArgError::NonUtf8Argument),
            };
        }
        if let Some((idx, key)) = self.index_of2(keys) {
            let raw = match self.0[idx].to_str() {
                Some(s) => s.to_string(),
                None => return Err(ArgError::NonUtf8Argument),
            };
            let mut start = key.len();
            let mut end = raw.len();
            if raw.as_bytes().get(start) == Some(&b'=') {
                start += 1;
            }
            if let Some(&c) = raw.as_bytes().get(start) {
                if c == b'"' || c == b'\'' {
                    start += 1;
                    if ends_with_byte(&raw[start..], c) {
                        end -= 1;
                    } else {
                        return Err(ArgError::OptionWithoutAValue(key));
                    }
                }
            }
            if end <= start {
                return Err(ArgError::OptionWithoutAValue(key));
            }
            self.0.remove(idx);
            return Ok(Some(raw[start..end].to_string()));
        }
        Ok(None)
    }

    pub fn opt_value_parsed<T, F>(
        &mut self,
        keys: &[&'static str],
        parse: F,
    ) -> Result<Option<T>, ArgError>
    where
        F: Fn(&str) -> Result<T, String>,
    {
        match self.opt_value(keys)? {
            None => Ok(None),
            Some(v) => match parse(&v) {
                Ok(t) => Ok(Some(t)),
                Err(cause) => Err(ArgError::ParsingFailed { value: v, cause }),
            },
        }
    }

    /// Remove an argument that matches exactly, returning whether it existed.
    pub fn remove_exact(&mut self, arg: &str) -> bool {
        if let Some(i) = self.0.iter().position(|v| v == OsStr::new(arg)) {
            self.0.remove(i);
            true
        } else {
            false
        }
    }

    pub fn finish(self) -> Vec<OsString> {
        self.0
    }
}
EOF
echo ok"}

