//! Parsing and manipulation of the "bounds" (fields / ranges / literals)
//! specification given on the command line.

use crate::fatal;
use std::fmt;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Side {
    Some(i64),
    Continue,
}

impl Side {
    fn parse(s: &str) -> Result<Side, String> {
        if s.is_empty() {
            return Ok(Side::Continue);
        }
        match s.parse::<i64>() {
            Ok(0) => Err("Zero is not a valid field".to_string()),
            Ok(v) => {
                if v == i64::MIN {
                    fatal::abort_with(fatal::LOC_SIDE_OVERFLOW, fatal::MSG_SIDE_OVERFLOW);
                }
                Ok(Side::Some(v))
            }
            Err(_) => Err(format!("Not a number `{}`", s)),
        }
    }

    /// Number of fields a line must have for this side to be addressable.
    pub fn needed(&self) -> usize {
        match self {
            Side::Some(v) => v.unsigned_abs() as usize,
            Side::Continue => 0,
        }
    }
}

#[derive(Clone, PartialEq, Debug)]
pub struct UserBounds {
    pub l: Side,
    pub r: Side,
    pub is_range: bool,
    pub fallback: Option<String>,
}

#[derive(Debug, Clone)]
pub enum BoundError {
    OutOfBounds(i64),
    LeftGreaterThanRight,
}

impl fmt::Display for BoundError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            BoundError::OutOfBounds(v) => write!(f, "Out of bounds: {}", v),
            BoundError::LeftGreaterThanRight => {
                write!(f, "Field left value cannot be greater than right value")
            }
        }
    }
}

impl UserBounds {
    pub fn single(v: i64) -> UserBounds {
        UserBounds {
            l: Side::Some(v),
            r: Side::Some(v),
            is_range: false,
            fallback: None,
        }
    }

    pub fn range(l: Side, r: Side) -> UserBounds {
        UserBounds {
            l,
            r,
            is_range: true,
            fallback: None,
        }
    }

    fn parse(s: &str) -> Result<UserBounds, String> {
        if s == ":" {
            return Err("Field format error, no numbers next to `:`".to_string());
        }
        if s.is_empty() {
            return Err("Field format error: empty field".to_string());
        }
        let (bounds_str, fallback) = match s.split_once('=') {
            Some((b, f)) => (b, Some(f.to_string())),
            None => (s, None),
        };
        let (l, r, is_range) = match bounds_str.split_once(':') {
            Some((ls, rs)) => {
                let l = Side::parse(ls)?;
                let r = Side::parse(rs)?;
                if let (Side::Some(a), Side::Some(b)) = (l, r) {
                    if (a > 0) == (b > 0) && a > b {
                        return Err(
                            "Field left value cannot be greater than right value".to_string(),
                        );
                    }
                }
                (l, r, true)
            }
            None => {
                let v = Side::parse(bounds_str)?;
                match v {
                    Side::Continue => (Side::Some(1), Side::Some(1), false),
                    v => (v, v, false),
                }
            }
        };
        Ok(UserBounds {
            l,
            r,
            is_range,
            fallback,
        })
    }

    /// Number of fields a line must have in order to satisfy this bound.
    pub fn needed(&self) -> usize {
        self.l.needed().max(self.r.needed())
    }

    pub fn is_negative(&self) -> bool {
        matches!(self.l, Side::Some(v) if v < 0) || matches!(self.r, Side::Some(v) if v < 0)
    }

    /// Start of the bound as a 1-based index (open start counts as 1).
    pub fn start_index(&self) -> i64 {
        match self.l {
            Side::Some(v) => v,
            Side::Continue => 1,
        }
    }

    /// End of the bound as a 1-based index, `None` when open ended.
    pub fn end_index(&self) -> Option<i64> {
        match self.r {
            Side::Some(v) => Some(v),
            Side::Continue => None,
        }
    }

    /// Resolve against `n` fields, strict variant: both sides must exist.
    /// Returns 0-based inclusive indices.
    pub fn resolve_strict(&self, n: usize) -> Result<(usize, usize), BoundError> {
        let n_i = n as i64;
        let start = match self.l {
            Side::Some(v) if v > 0 => {
                if v - 1 >= n_i {
                    return Err(BoundError::OutOfBounds(v));
                }
                (v - 1) as usize
            }
            Side::Some(v) => {
                if n_i + v < 0 {
                    return Err(BoundError::OutOfBounds(v));
                }
                (n_i + v) as usize
            }
            Side::Continue => 0,
        };
        if !self.is_range {
            return Ok((start, start));
        }
        let end = match self.r {
            Side::Some(v) if v > 0 => {
                if v - 1 >= n_i {
                    return Err(BoundError::OutOfBounds(v));
                }
                (v - 1) as usize
            }
            Side::Some(v) => {
                if n_i + v < 0 {
                    return Err(BoundError::OutOfBounds(v));
                }
                (n_i + v) as usize
            }
            Side::Continue => n - 1,
        };
        if start > end {
            return Err(BoundError::LeftGreaterThanRight);
        }
        Ok((start, end))
    }

    /// Resolve against `n` fields, lenient variant: the right side is clamped
    /// to the available fields. Returns 0-based inclusive indices.
    pub fn resolve_clamped(&self, n: usize) -> Result<(usize, usize), BoundError> {
        let n_i = n as i64;
        let start = match self.l {
            Side::Some(v) if v > 0 => {
                if v - 1 >= n_i {
                    return Err(BoundError::OutOfBounds(v));
                }
                (v - 1) as usize
            }
            Side::Some(v) => {
                if n_i + v < 0 {
                    return Err(BoundError::OutOfBounds(v));
                }
                (n_i + v) as usize
            }
            Side::Continue => 0,
        };
        if !self.is_range {
            return Ok((start, start));
        }
        let end = match self.r {
            Side::Some(v) if v > 0 => {
                let v = v as u64 as usize;
                v.min(n) - 1
            }
            Side::Some(v) => n.saturating_sub(v.unsigned_abs() as usize),
            Side::Continue => n - 1,
        };
        if start > end {
            return Err(BoundError::LeftGreaterThanRight);
        }
        Ok((start, end))
    }
}

impl fmt::Display for UserBounds {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match (self.l, self.r) {
            (Side::Some(a), Side::Some(b)) if a == b => write!(f, "{}", a),
            (l, r) => {
                match l {
                    Side::Some(v) => write!(f, "{}", v)?,
                    Side::Continue => write!(f, "1")?,
                }
                write!(f, ":")?;
                match r {
                    Side::Some(v) => write!(f, "{}", v),
                    Side::Continue => Ok(()),
                }
            }
        }
    }
}

