//! Cut a single record (a line) according to the configured bounds.

use crate::bounds::{BoundError, BoundsList, Piece, UserBounds};
use crate::errors::Result;
use crate::fatal;
use crate::options::{BoundsType, Opt, Trim};
use regex::bytes::Regex;
use std::io::Write;
use std::sync::OnceLock;

fn chars_regex() -> &'static Regex {
    static RE: OnceLock<Regex> = OnceLock::new();
    RE.get_or_init(|| Regex::new(r"\b|\B").expect("valid regex"))
}

/// Find all non-overlapping occurrences of `needle` in `hay`.
/// An empty needle matches at every position (including the end).
fn find_all(hay: &[u8], needle: &[u8]) -> Vec<(usize, usize)> {
    let mut out = Vec::new();
    if needle.is_empty() {
        for i in 0..=hay.len() {
            out.push((i, i));
        }
        return out;
    }
    if needle.len() == 1 {
        for p in memchr::memchr_iter(needle[0], hay) {
            out.push((p, p + 1));
        }
        return out;
    }
    let finder = memchr::memmem::Finder::new(needle);
    let mut start = 0;
    while start <= hay.len() {
        match finder.find(&hay[start..]) {
            Some(p) => {
                let s = start + p;
                out.push((s, s + needle.len()));
                start = s + needle.len();
            }
            None => break,
        }
    }
    out
}

fn delimiter_matches(line: &[u8], opt: &Opt) -> Vec<(usize, usize)> {
    match &opt.regex {
        Some(re) => re.find_iter(line).map(|m| (m.start(), m.end())).collect(),
        None => find_all(line, &opt.delimiter),
    }
}

/// Remove leading and/or trailing delimiters.
fn trim_line<'a>(line: &'a [u8], opt: &Opt) -> &'a [u8] {
    let trim = match opt.trim {
        Some(t) => t,
        None => return line,
    };
    if !matches!(opt.bounds_type, BoundsType::Fields | BoundsType::Lines) {
        return line;
    }
    let mut cur = line;
    match &opt.regex {
        Some(re) => {
            if matches!(trim, Trim::Left | Trim::Both) {
                loop {
                    match re.find(cur) {
                        Some(m) if m.start() == 0 && m.end() > 0 => cur = &cur[m.end()..],
                        _ => break,
                    }
                }
            }
            if matches!(trim, Trim::Right | Trim::Both) {
                loop {
                    let last = re.find_iter(cur).last();
                    match last {
                        Some(m) if m.end() == cur.len() && m.start() < cur.len() => {
                            cur = &cur[..m.start()]
                        }
                        _ => break,
                    }
                }
            }
        }
        None => {
            let d = opt.delimiter.as_slice();
            if d.is_empty() {
                return line;
            }
            if matches!(trim, Trim::Left | Trim::Both) {
                while cur.starts_with(d) {
                    cur = &cur[d.len()..];
                }
            }
            if matches!(trim, Trim::Right | Trim::Both) {
                while cur.ends_with(d) {
                    cur = &cur[..cur.len() - d.len()];
                }
            }
        }
    }
    cur
}

/// Collapse runs of adjacent delimiters into a single one.
fn compress_line(line: &[u8], opt: &Opt, buf: &mut Vec<u8>) {
    buf.clear();
    let matches = delimiter_matches(line, opt);
    let mut pos = 0;
    let mut prev_end: Option<usize> = None;
    for (s, e) in matches {
        if prev_end == Some(s) && e > s {
            // adjacent to the previous delimiter: drop it
            pos = e;
            prev_end = Some(e);
            continue;
        }
        buf.extend_from_slice(&line[pos..e]);
        pos = e;
        prev_end = Some(e);
    }
    buf.extend_from_slice(&line[pos..]);
}

/// Split the record into field ranges.
fn extract_fields(line: &[u8], opt: &Opt) -> Vec<(usize, usize)> {
    let mut fields = Vec::new();
    if opt.bounds_type == BoundsType::Characters {
        let mut prev = 0;
        for m in chars_regex().find_iter(line) {
            let p = m.start();
            if p > prev {
                fields.push((prev, p));
                prev = p;
            }
        }
        if line.len() > prev || fields.is_empty() {
            fields.push((prev, line.len()));
        }
        return fields;
    }
    let matches = delimiter_matches(line, opt);
    let mut start = 0;
    let mut prev_end: Option<usize> = None;
    for (s, e) in matches {
        if opt.greedy && prev_end == Some(s) {
            start = e;
            prev_end = Some(e);
            continue;
        }
        fields.push((start, s));
        start = e;
        prev_end = Some(e);
    }
    fields.push((start, line.len()));
    fields
}

fn write_json_string<W: Write>(out: &mut W, s: &[u8]) -> std::io::Result<()> {
    out.write_all(b"\"")?;
    let mut start = 0;
    for (i, &b) in s.iter().enumerate() {
        let esc: Option<Vec<u8>> = match b {
            b'"' => Some(b"\\\"".to_vec()),
            b'\\' => Some(b"\\\\".to_vec()),
            0x08 => Some(b"\\b".to_vec()),
            0x0c => Some(b"\\f".to_vec()),
            b'\n' => Some(b"\\n".to_vec()),
            b'\r' => Some(b"\\r".to_vec()),
            b'\t' => Some(b"\\t".to_vec()),
            c if c < 0x20 => Some(format!("\\u{:04x}", c).into_bytes()),
            _ => None,
        };
        if let Some(e) = esc {
            out.write_all(&s[start..i])?;
            out.write_all(&e)?;
            start = i + 1;
        }
    }
    out.write_all(&s[start..])?;
    out.write_all(b"\"")
}

/// Replace every delimiter occurrence inside `slice`.
fn write_replaced<W: Write>(out: &mut W, slice: &[u8], opt: &Opt, replacement: &[u8]) -> std::io::Result<()> {
    match &opt.regex {
        Some(re) => {
            let replaced = re.replace_all(slice, replacement);
            out.write_all(&replaced)
        }
        None => {
            let mut pos = 0;
            for (s, e) in find_all(slice, &opt.delimiter) {
                out.write_all(&slice[pos..s])?;
                out.write_all(replacement)?;
                pos = e;
            }
            out.write_all(&slice[pos..])
        }
    }
}

fn fallback_for<'a>(b: &'a UserBounds, opt: &'a Opt) -> Option<&'a [u8]> {
    match &b.fallback {
        Some(f) => Some(f.as_bytes()),
        None => opt.fallback_oob.as_deref(),
    }
}

fn last_field_index(pieces: &[Piece]) -> Option<usize> {
    pieces.iter().rposition(|p| matches!(p, Piece::Field(_)))
}

/// Fast lane: plain single byte delimiter, no transformation of the fields.
fn fast_path_applicable(opt: &Opt) -> bool {
    opt.bounds_type == BoundsType::Fields
        && opt.delimiter.len() == 1
        && opt.regex.is_none()
        && !opt.greedy
        && !opt.compress
        && opt.replace.is_none()
        && !opt.complement
        && !opt.json
}

fn cut_fast<W: Write>(line: &[u8], opt: &Opt, out: &mut W) -> Result<()> {
    let d = opt.delimiter[0];
    if opt.only_delimited && memchr::memchr(d, line).is_none() {
        return Ok(());
    }
    let mut fields: Vec<(usize, usize)> = Vec::new();
    let mut start = 0;
    for p in memchr::memchr_iter(d, line) {
        fields.push((start, p));
        start = p + 1;
    }
    fields.push((start, line.len()));
    let n = fields.len();

    let pieces = &opt.bounds.pieces;
    let last_field = last_field_index(pieces);
    for (i, piece) in pieces.iter().enumerate() {
        match piece {
            Piece::Literal(s) => out.write_all(s.as_bytes())?,
            Piece::Field(b) => {
                match b.resolve_clamped(n) {
                    Ok((s, e)) => out.write_all(&line[fields[s].0..fields[e].1])?,
                    Err(err) => match fallback_for(b, opt) {
                        Some(fb) => out.write_all(fb)?,
                        None => return Err(err.into()),
                    },
                }
                if opt.join && Some(i) != last_field {
                    out.write_all(&opt.delimiter)?;
                }
            }
        }
    }
    out.write_all(&[opt.eol])?;
    Ok(())
}

fn cut_general<W: Write>(line: &[u8], opt: &Opt, out: &mut W) -> Result<()> {
    let fields = extract_fields(line, opt);
    let n = fields.len();
    let needed = opt.bounds.needed();
    let num_fields = if n >= needed { Some(n) } else { None };

    if opt.only_delimited {
        match num_fields {
            Some(1) => return Ok(()),
            Some(_) => {}
            None => fatal::abort_with(
                fatal::LOC_NO_FIELD_COUNT_ONLY_DELIMITED,
                fatal::MSG_NO_FIELD_COUNT,
            ),
        }
    }

    if opt.json {
        out.write_all(b"[")?;
    }

    let mut pieces: Vec<Piece> = if opt.complement {
        let count = match num_fields {
            Some(c) => c,
            None => fatal::abort_with(
                fatal::LOC_NO_FIELD_COUNT_COMPLEMENT,
                fatal::MSG_NO_FIELD_COUNT,
            ),
        };
        let c = opt.bounds.complement(count);
        if !c.iter().any(|p| matches!(p, Piece::Field(_))) {
            return Err("the complement is empty".to_string().into());
        }
        c
    } else {
        opt.bounds.pieces.clone()
    };

    if opt.json || opt.bounds_type == BoundsType::Characters {
        pieces = BoundsList::unpack(&pieces, num_fields);
        if pieces.is_empty() {
            fatal::abort_with(fatal::LOC_EMPTY_BOUNDS_LIST, fatal::MSG_EMPTY_BOUNDS_LIST);
        }
    }

    if opt.json {
        let mut first = true;
        for piece in &pieces {
            if let Piece::Field(b) = piece {
                let value: &[u8] = match b.resolve_strict(n) {
                    Ok((s, e)) => &line[fields[s].0..fields[e].1],
                    Err(err) => match fallback_for(b, opt) {
                        Some(fb) => fb,
                        None => return Err(err.into()),
                    },
                };
                if !first {
                    out.write_all(b",")?;
                }
                first = false;
                write_json_string(out, value)?;
            }
        }
        out.write_all(b"]")?;
        out.write_all(&[opt.eol])?;
        return Ok(());
    }

    let last_field = last_field_index(&pieces);
    let replace_inside =
        opt.replace.is_some() && matches!(opt.bounds_type, BoundsType::Fields | BoundsType::Lines);
    for (i, piece) in pieces.iter().enumerate() {
        match piece {
            Piece::Literal(s) => out.write_all(s.as_bytes())?,
            Piece::Field(b) => {
                match b.resolve_strict(n) {
                    Ok((s, e)) => {
                        let slice = &line[fields[s].0..fields[e].1];
                        if replace_inside {
                            write_replaced(out, slice, opt, opt.replace.as_deref().unwrap())?;
                        } else {
                            out.write_all(slice)?;
                        }
                    }
                    Err(err) => match fallback_for(b, opt) {
                        Some(fb) => out.write_all(fb)?,
                        None => return Err(err.into()),
                    },
                }
                if opt.join && Some(i) != last_field {
                    out.write_all(opt.join_text())?;
                }
            }
        }
    }
    out.write_all(&[opt.eol])?;
    Ok(())
}

/// Process one record.
pub fn cut_str<W: Write>(line: &[u8], opt: &Opt, out: &mut W, buf: &mut Vec<u8>) -> Result<()> {
    let line = trim_line(line, opt);
    let line: &[u8] = if opt.compress && matches!(opt.bounds_type, BoundsType::Fields | BoundsType::Lines) {
        compress_line(line, opt, buf);
        buf.as_slice()
    } else {
        line
    };

    if line.is_empty() {
        if !opt.only_delimited {
            out.write_all(&[opt.eol])?;
        }
        return Ok(());
    }

    if fast_path_applicable(opt) {
        cut_fast(line, opt, out)
    } else {
        cut_general(line, opt, out)
    }
}

#[allow(dead_code)]
pub fn bound_error_to_string(e: &BoundError) -> String {
    e.to_string()
}
EOF
echo ok"}

