use crate::bounds::Piece;
use crate::errors::{Result, RunError};
use crate::options::Opt;
use std::io::{BufRead, Write};

/// Can the streaming strategy be used with this configuration?
pub fn applicable(opt: &Opt) -> bool {
    !opt.complement && !opt.compress && !opt.bounds.has_negative() && opt.bounds.is_ordered()
}

pub fn cut_lines<R: BufRead, W: Write>(reader: &mut R, opt: &Opt, out: &mut W) -> Result<()> {
    let pieces = &opt.bounds.pieces;
    let eol = opt.eol;
    let mut k = 0usize;
    let mut line_idx: i64 = 0;
    let mut buf: Vec<u8> = Vec::new();

    // emit leading literals when processing the first line
    loop {
        if k >= pieces.len() {
            break;
        }
        buf.clear();
        let read = reader.read_until(eol, &mut buf)?;
        if read == 0 {
            break;
        }
        if eol == b'\n' {
            // the reference reads UTF-8 text here
            if std::str::from_utf8(&buf).is_err() {
                return Err(RunError::Io(std::io::Error::new(
                    std::io::ErrorKind::InvalidData,
                    "stream did not contain valid UTF-8",
