            match &pieces[k] {
                Piece::Literal(s) => {
                    out.write_all(s.as_bytes())?;
                    k += 1;
                    if k < pieces.len() && opt.join {
                        out.write_all(&[eol])?;
                    }
                }
                Piece::Field(b) => {
                    let start = b.start_index();
                    let end = b.end_index();
                    if line_idx < start {
                        break;
                    }
                    // within the bound
                    if line_idx > start {
                        out.write_all(&[eol])?;
                    }
                    out.write_all(&buf)?;
                    if end == Some(line_idx) {
                        k += 1;
                        if k < pieces.len() && opt.join {
                            out.write_all(&[eol])?;
                        }
                        // the same line may satisfy following bounds too
                        continue;
                    }
                    break;
                }
            }
        }
    }

    if k < pieces.len() {
        if let Piece::Field(b) = &pieces[k] {
            if b.end_index().is_some() {
                return Err(format!("Out of bounds: {}", b).into());
            }
        }
    }
    out.write_all(&[eol])?;
    Ok(())
}
