//! `--fixed-memory`: forward-only streaming over fields.

use crate::bounds::{Piece, UserBounds};
use crate::errors::Result;
use crate::options::Opt;
use std::io::{BufRead, Write};

struct LineState<'a> {
    pieces: &'a [Piece],
    /// index of the current piece
    ptr: usize,
    /// did the last field piece complete thanks to a delimiter (not EOL)?
    completed_by_delimiter: bool,
}

fn emit_literals<W: Write>(st: &mut LineState, out: &mut W) -> Result<()> {
    while st.ptr < st.pieces.len() {
        match &st.pieces[st.ptr] {
            Piece::Literal(s) => {
                out.write_all(s.as_bytes())?;
                st.ptr += 1;
            }
            Piece::Field(_) => break,
        }
    }
    Ok(())
}

fn fallback_for<'a>(b: &'a UserBounds, opt: &'a Opt) -> Option<&'a [u8]> {
    match &b.fallback {
        Some(f) => Some(f.as_bytes()),
        None => opt.fallback_oob.as_deref(),
    }
}

/// A field (1-based `idx`) has been fully read.
fn complete_field<W: Write>(
    st: &mut LineState,
    idx: i64,
    content: &[u8],
    by_delimiter: bool,
    opt: &Opt,
    out: &mut W,
) -> Result<()> {
    if st.ptr >= st.pieces.len() {
        return Ok(());
    }
    let b = match &st.pieces[st.ptr] {
        Piece::Field(b) => b,
        Piece::Literal(_) => return Ok(()),
    };
    let start = b.start_index();
    let end = b.end_index();
    if idx < start {
        return Ok(());
    }
    if let Some(e) = end {
        if idx > e {
            return Ok(());
        }
    }
    if idx > 1 && (opt.join || idx != start) {
        out.write_all(opt.join_text())?;
    }
    out.write_all(content)?;
    if end == Some(idx) {
        st.ptr += 1;
        st.completed_by_delimiter = by_delimiter;
        emit_literals(st, out)?;
    }
    Ok(())
}

fn finish_line<W: Write>(st: &mut LineState, has_eol: bool, opt: &Opt, out: &mut W) -> Result<()> {
    if !has_eol && st.ptr >= st.pieces.len() && st.completed_by_delimiter {
        // quirk of the reference implementation: trailing literals are
        // emitted again when the input ends without a line terminator
        let last_field = st.pieces.iter().rposition(|p| matches!(p, Piece::Field(_)));
        if let Some(lf) = last_field {
            for p in &st.pieces[lf + 1..] {
                if let Piece::Literal(s) = p {
                    out.write_all(s.as_bytes())?;
                }
            }
        }
    }
    while st.ptr < st.pieces.len() {
        match &st.pieces[st.ptr] {
            Piece::Literal(s) => {
                out.write_all(s.as_bytes())?;
                st.ptr += 1;
            }
            Piece::Field(b) => {
                if b.end_index().is_none() {
                    // open ended range: nothing more to do
                    break;
                }
                match fallback_for(b, opt) {
                    Some(fb) => {
                        out.write_all(fb)?;
                        st.ptr += 1;
                    }
                    None => {
                        return Err(format!("Out of bounds: {}", b.start_index()).into());
                    }
                }
            }
        }
    }
    out.write_all(&[opt.eol])?;
    Ok(())
}

fn process_line<W: Write>(line: &[u8], has_eol: bool, opt: &Opt, out: &mut W) -> Result<()> {
    let d = opt.delimiter[0];
    let mut st = LineState {
        pieces: &opt.bounds.pieces,
        ptr: 0,
        completed_by_delimiter: false,
    };
    emit_literals(&mut st, out)?;

    let mut field_idx: i64 = 1;
    let mut field_start = 0usize;
    for p in memchr::memchr_iter(d, line) {
        if p == 0 {
            // quirk: a delimiter at the very start of the line does not
            // complete the (empty) first field
            field_idx += 1;
            field_start = 1;
            continue;
        }
        complete_field(&mut st, field_idx, &line[field_start..p], true, opt, out)?;
        field_idx += 1;
        field_start = p + 1;
    }
    if !line.is_empty() && (field_start < line.len() || has_eol) {
        complete_field(&mut st, field_idx, &line[field_start..], false, opt, out)?;
    }
    finish_line(&mut st, has_eol, opt, out)
}

pub fn cut_stream<R: BufRead, W: Write>(reader: &mut R, opt: &Opt, out: &mut W) -> Result<()> {
    let eol = opt.eol;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let read = reader.read_until(eol, &mut buf)?;
        if read == 0 {
            break;
        }
        let has_eol = buf.last() == Some(&eol);
        if has_eol {
            buf.pop();
        }
        process_line(&buf, has_eol, opt, out)?;
    }
    Ok(())
}
