                    }
                }
            }
        }
    }
    out.write_all(&[opt.eol])?;
    Ok(())
}

fn process_line<W: Write>(line: &[u8], has_eol: bool, opt: &Opt, out: &mut W) -> Result<()> {
    let d = opt.delimiter[0];
    let mut st = LineState {
        pieces: &opt.bounds.pieces,
        ptr: 0,
        completed_by_delimiter: false,
    };
    emit_literals(&mut st, out)?;

    let mut field_idx: i64 = 1;
    let mut field_start = 0usize;
    for p in memchr::memchr_iter(d, line) {
        if p == 0 {
            // quirk: a delimiter at the very start of the line does not
            // complete the (empty) first field
            field_idx += 1;
            field_start = 1;
            continue;
        }
        complete_field(&mut st, field_idx, &line[field_start..p], true, opt, out)?;
        field_idx += 1;
        field_start = p + 1;
    }
    if !line.is_empty() && (field_start < line.len() || has_eol) {
        complete_field(&mut st, field_idx, &line[field_start..], false, opt, out)?;
    }
    finish_line(&mut st, has_eol, opt, out)
}

pub fn cut_stream<R: BufRead, W: Write>(reader: &mut R, opt: &Opt, out: &mut W) -> Result<()> {
    let eol = opt.eol;
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let read = reader.read_until(eol, &mut buf)?;
        if read == 0 {
            break;
        }
        let has_eol = buf.last() == Some(&eol);
        if has_eol {
            buf.pop();
        }
        process_line(&buf, has_eol, opt, out)?;
    }
    Ok(())
}
