            Ok(re) => opt.regex = Some(re),
            Err(e) => runtime_error(&format!("The regular expression is malformed. {}", e)),
        }
        if opt.join && opt.replace.is_none() {
            runtime_error("Cannot use --regex and --join without --replace-delimiter");
        }
        if opt.compress && opt.replace.is_none() {
            runtime_error("Cannot use --regex and --compress-delimiter without --replace-delimiter");
        }
    }
    if opt.fixed_memory_kb.is_some() {
        if opt.delimiter.len() != 1 {
            runtime_error("Delimiter must be 1 byte wide for FastOpt");
        }
        if opt.bounds_type != BoundsType::Fields
            || opt.regex.is_some()
            || opt.compress
            || opt.greedy
            || opt.trim.is_some()
            || opt.only_delimited
            || opt.complement
            || opt.json
        {
            runtime_error(
                "StreamOpt supports solely forward fields, join and single-character delimiters",
            );
        }
        if !opt.bounds.is_forward() {
            runtime_error("Bounds cannot be converted to ForwardBounds");
        }
    }
}

/// Iterate over the records of `data`, calling `f` for each one.
fn for_each_line<F>(data: &[u8], eol: u8, mut f: F) -> Result<()>
where
    F: FnMut(&[u8]) -> Result<()>,
{
    let mut start = 0;
    while start < data.len() {
        let end = match memchr::memchr(eol, &data[start..]) {
            Some(p) => start + p,
            None => {
                f(&data[start..])?;
                break;
            }
        };
        let mut line = &data[start..end];
        if eol == b'\n' && line.last() == Some(&b'\r') {
            line = &line[..line.len() - 1];
        }
        f(line)?;
        start = end + 1;
    }
    Ok(())
}

fn read_lines_streaming<R: BufRead, F>(reader: &mut R, eol: u8, mut f: F) -> Result<()>
where
    F: FnMut(&[u8]) -> Result<()>,
{
    let mut buf: Vec<u8> = Vec::new();
    loop {
        buf.clear();
        let read = reader.read_until(eol, &mut buf)?;
        if read == 0 {
            break;
        }
        let mut line: &[u8] = &buf;
        if line.last() == Some(&eol) {
            line = &line[..line.len() - 1];
            if eol == b'\n' && line.last() == Some(&b'\r') {
                line = &line[..line.len() - 1];
            }
        }
        f(line)?;
    }
    Ok(())
}

fn read_file(path: &str) -> Result<Vec<u8>> {
    match std::fs::read(path) {
        Ok(d) => Ok(d),
        Err(e) => Err(RunError::Msg(format!(
            "{}.\nWas attempting to read {:?}",
            e, path
        ))),
    }
}

fn run(opt: &Opt, out: &mut impl Write) -> Result<()> {
    let stdin = std::io::stdin();

    if opt.bounds_type == BoundsType::Bytes {
        let data = match &opt.path {
            Some(p) => read_file(p)?,
            None => {
                let mut v = Vec::new();
                stdin.lock().read_to_end(&mut v)?;
                v
            }
        };
        return cut_bytes::cut_bytes(&data, opt, out);
    }

    if opt.fixed_memory_kb.is_some() {
        return match &opt.path {
            Some(p) => {
                let file = std::fs::File::open(p).map_err(|e| {
                    RunError::Msg(format!("{}.\nWas attempting to read {:?}", e, p))
                })?;
                let mut reader = BufReader::new(file);
                stream::cut_stream(&mut reader, opt, out)
            }
            None => {
                let mut reader = stdin.lock();
                stream::cut_stream(&mut reader, opt, out)
            }
        };
    }

    if opt.bounds_type == BoundsType::Lines && cut_lines::applicable(opt) {
        return match &opt.path {
            Some(p) => {
                let file = std::fs::File::open(p).map_err(|e| {
                    RunError::Msg(format!("{}.\nWas attempting to read {:?}", e, p))
                })?;
                let mut reader = BufReader::new(file);
                cut_lines::cut_lines(&mut reader, opt, out)
            }
            None => {
                let mut reader = stdin.lock();
                cut_lines::cut_lines(&mut reader, opt, out)
            }
        };
    }

    let mut buf: Vec<u8> = Vec::new();
    match &opt.path {
        Some(p) => {
            let data = read_file(p)?;
            for_each_line(&data, opt.eol, |line| cut_str::cut_str(line, opt, out, &mut buf))
        }
        None => {
            let mut reader = stdin.lock();
            read_lines_streaming(&mut reader, opt.eol, |line| {
                cut_str::cut_str(line, opt, out, &mut buf)
            })
        }
    }
}

fn main() {
    let parsed = parse_args();
    let mut opt = parsed.opt;
    validate(&mut opt);

    let stdout = std::io::stdout();
    let mut out = std::io::BufWriter::with_capacity(64 * 1024, stdout.lock());
    let result = run(&opt, &mut out);
    let flush_result = out.flush();
    drop(out);

    if let Err(e) = result {
        if is_broken_pipe(&e) {
            std::process::exit(0);
        }
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
    if let Err(e) = flush_result {
        if e.kind() == std::io::ErrorKind::BrokenPipe {
            std::process::exit(0);
        }
        eprintln!("Error: {}", e);
        std::process::exit(1);
    }
}
