    if random.random() < 0.15:
        args += ['-r', random.choice(['X', '', '$1', 'xy'])]
    if random.random() < 0.15:
        args += ['-t', random.choice(['l', 'r', 'b', 'L'])]
    if random.random() < 0.1:
        args += ['--fallback-oob', random.choice(['Q', ''])]
    if random.random() < 0.1:
        args += ['-M', random.choice(['1', '0', '2'])]
