    if random.random() < 0.15:
        pairs.append(['-r', random.choice(['X', '', '$1', 'xy'])])
    if random.random() < 0.15:
        pairs.append(['-t', random.choice(['l', 'r', 'b', 'L'])])
    if random.random() < 0.1:
        pairs.append(['--fallback-oob', random.choice(['Q', ''])])
    if random.random() < 0.1:
        pairs.append(['-M', random.choice(['1', '0', '2'])])
    random.shuffle(pairs)
    return [t for p in pairs for t in p]

import re
def norm(err):
