import random, sys, os, subprocess, re
random.seed(int(sys.argv[1]) if len(sys.argv) > 1 else 0)
N = int(sys.argv[2]) if len(sys.argv) > 2 else 300
REF = '/workspace/executable'
MINE = '/workspace/target/release/tuc'

def rand_line():
    n = random.randint(0, 10)
    return ''.join(random.choice('ab-- ,x\xe9') for _ in range(n))

def rand_input():
    k = random.randint(0, 6)
    lines = [rand_line() for _ in range(k)]
    s = '\n'.join(lines)
    if random.random() < 0.6 and k > 0:
        s += '\n'
    if random.random() < 0.1:
        s = s.replace('\n', '\r\n')
    return s.encode('utf-8')

def rand_side(allow_neg=True):
    r = random.random()
    if r < 0.6:
        return str(random.randint(1, 6))
    elif r < 0.85 and allow_neg:
        return str(-random.randint(1, 6))
    return ''

def rand_bound(allow_neg=True):
    r = random.random()
    if r < 0.5:
        s = rand_side(allow_neg)
        if s == '': s = '1'
    else:
        a, b = rand_side(allow_neg), rand_side(allow_neg)
        s = a + ':' + b
        if s == ':': s = '1:'
    if random.random() < 0.15:
        s += '=' + random.choice(['X', 'fb', ''])
    return s

def rand_bounds(allow_neg=True):
    k = random.randint(1, 4)
    bs = [rand_bound(allow_neg) for _ in range(k)]
    if random.random() < 0.2:
        parts = []
        for b in bs:
            if random.random() < 0.5:
                parts.append(random.choice(['x', ' ', '{{', '}}', '-', 'zz']))
            parts.append('{' + b + '}')
        if random.random() < 0.4:
            parts.append(random.choice(['y', '}}', ' end']))
        return ''.join(parts)
    return ','.join(bs)

def rand_args():
    pairs = []
    mode = random.choice(['f', 'c', 'b', 'l', 'l', 'l', 'M', 'M', 'json'])
    if mode == 'M':
        pairs.append(['-f', rand_bounds(allow_neg=random.random() < 0.2)])
        pairs.append(['-M', random.choice(['1', '1', '2', '0'])])
        if random.random() < 0.5: pairs.append(['-j'])
        if random.random() < 0.3: pairs.append(['-r', random.choice(['X', 'XY', ''])])
